import React from 'react';
import { FaMoon, FaSun, FaInfoCircle, FaSignOutAlt } from 'react-icons/fa';
import { useAuth } from '../utils/AuthContext';
import './Header.css';

const Header = ({ currentPage, setCurrentPage, darkMode, toggleDarkMode, currentUser }) => {
  const { logout } = useAuth();

  const handleLogout = () => {
    logout();
    window.location.href = '/login';
  };

  return (
    <header className="app-header">
      <div className="branding">
        <h1 className="glitter-title">CRM System</h1>
        <span className="user-info">
          Welcome, {currentUser?.name} ({currentUser?.role})
        </span>
      </div>

      <nav className="nav-tabs">
        <button
          className={currentPage === 'home' ? 'nav-tab active' : 'nav-tab'}
          onClick={() => setCurrentPage('home')}
        >Home</button>
        
        <button
          className={currentPage === 'dashboard' ? 'nav-tab active' : 'nav-tab'}
          onClick={() => setCurrentPage('dashboard')}
        >Dashboard</button>
        
        <button
          className={currentPage === 'customers' ? 'nav-tab active' : 'nav-tab'}
          onClick={() => setCurrentPage('customers')}
        >Customers</button>
        
        <button
          className={currentPage === 'interactions' ? 'nav-tab active' : 'nav-tab'}
          onClick={() => setCurrentPage('interactions')}
        >Interactions</button>
        
        <button
          className={currentPage === 'orders' ? 'nav-tab active' : 'nav-tab'}
          onClick={() => setCurrentPage('orders')}
        >Orders</button>
        
        <button
          className={currentPage === 'tasks' ? 'nav-tab active' : 'nav-tab'}
          onClick={() => setCurrentPage('tasks')}
        >Tasks</button>
        
        {currentUser?.role === 'ADMIN' && (
          <button
            className={currentPage === 'admin' ? 'nav-tab active' : 'nav-tab'}
            onClick={() => setCurrentPage('admin')}
          >Admin</button>
        )}
        
        <button
          className={currentPage === 'about' ? 'nav-tab active' : 'nav-tab'}
          onClick={() => setCurrentPage('about')}
        >
          <FaInfoCircle style={{ marginRight: "6px", verticalAlign: "middle" }} /> About
        </button>
      </nav>

      <div className="header-controls">
        <span
          className="darkmode-toggle"
          onClick={toggleDarkMode}
          title="Toggle Dark Mode"
          role="button"
          tabIndex={0}
        >
          {darkMode ? <FaSun size={22} /> : <FaMoon size={22} />}
        </span>
        
        <button className="logout-btn" onClick={handleLogout}>
          <FaSignOutAlt /> Logout
        </button>
      </div>
    </header>
  );
};

export default Header;
